<script setup lang="ts">
import { onMounted,onUnmounted,ref } from 'vue'
import { ElAlert,ElButton,ElTag,ElDialog,ElCheckbox } from 'element-plus'
import type { API } from '../../../shared/api'
import { dateLabel,isCancelled } from '../../../shared/console'
import { channelLabel,processingLabel } from '../../../shared/memoryStatus'
const props=defineProps<{api:API}>(),emit=defineEmits<{open:[page:string];source:[id:string]}>()
const data=ref<any>(null),loading=ref(false),error=ref(''),retry=ref<any>(null),checked=ref(false)
let alive=true,timer:ReturnType<typeof setTimeout>
const labels:Record<string,string>={pending:'待处理',running:'处理中',retry:'等待重试',failed:'失败',completed:'已完成',ready:'已就绪',starting:'启动中',degraded:'部分未连接',stopped:'已停止',unavailable:'未提供'}
async function load(){clearTimeout(timer);loading.value=true;error.value='';try{const result=await props.api.request('/studio/pipeline',undefined,'GET','pipeline');if(alive)data.value=result}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive){loading.value=false;timer=setTimeout(()=>void load(),5000)}}}
async function retryJob(){if(!retry.value||!checked.value)return;loading.value=true;try{await props.api.request('/memory-jobs/'+encodeURIComponent(retry.value.id)+'/retry',{});retry.value=null;await load()}catch(e){if(alive&&!isCancelled(e))error.value=(e as Error).message}finally{if(alive)loading.value=false}}
onMounted(load);onUnmounted(()=>{alive=false;clearTimeout(timer)})
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><section class="panel"><div class="section-title"><div><h2>记忆处理与服务状态</h2><p>查看历史为什么没有变成长期记忆；刷新只读取状态，不启动模型或实验。</p></div><el-button :loading="loading" @click="load">刷新状态</el-button></div><p v-if="!data" role="status">{{ loading?'正在读取处理状态…':'未能读取状态，请点击刷新重试。' }}</p><template v-else><div class="info-note"><strong>当前策略：{{ data.approval_policy?.mode==='llm'?'LLM主审，人工辅助':'人工审核' }}</strong><p>{{ data.approval_policy?.default }}</p></div><div class="pipeline-steps"><button @click="emit('open','conversations')"><span>1 · 保存对话</span><strong>{{ data.counts.sessions }} <small>段</small></strong><p>本人聊天 {{ data.counts.native_conversations }} · 导入资料 {{ data.counts.imported_conversations }}</p></button><button><span>2 · 提取候选</span><strong>{{ data.extraction.statuses.completed??0 }} <small>次已处理</small></strong><p>后台任务 {{ data.extraction.worker==='running'?'运行中':labels[data.extraction.worker]??data.extraction.worker }}</p></button><button @click="emit('open','reviews')"><span>3 · 核对与审核</span><strong>{{ data.counts.reviews.pending??0 }} <small>条待审</small></strong><p>低风险LLM自动入库，疑问留人工</p></button><button @click="emit('open','memories')"><span>4 · 长期记忆</span><strong>{{ data.counts.memories }} <small>条有效</small></strong><p>批准后参与后续记忆访问</p></button></div><div class="pipeline-explanations"><p v-for="item in data.reasons" :key="item.code">{{ item.text }}</p></div><div class="actions"><el-button type="primary" @click="emit('open','conversations')">从本人原话提出候选</el-button><el-button @click="emit('open','reviews')">前往候选审核</el-button></div></template></section><template v-if="data"><section class="panel"><h2>最近的提取任务</h2><p>展示最近 {{ data.extraction.recent_limit }} 条任务。旧记录缺少抽取计数时明确标为“未记录”，不补造模型结果。</p><table v-if="data.extraction.recent.length" class="data-table"><thead><tr><th>记录时间</th><th>渠道 / 处理结果</th><th>本次抽取</th><th>已保存候选</th><th>尝试</th><th>操作</th></tr></thead><tbody><tr v-for="job in data.extraction.recent" :key="job.id"><td>{{ dateLabel(job.created_at,true) }}</td><td><el-tag :type="job.status==='failed'?'danger':job.status==='completed'?'success':'info'">{{ labels[job.status]??job.status }}</el-tag><p>{{ channelLabel(job.origin) }}</p><p>{{ processingLabel(job.memory_processing) }}</p></td><td>{{ job.extracted_count??'未记录' }}</td><td>{{ job.review_count }}</td><td>{{ job.attempts }}</td><td><el-button v-if="job.session_id" size="small" @click="emit('source',job.source_ref)">查看原话</el-button><el-button v-if="job.status==='failed'" size="small" @click="retry=job;checked=false">重试…</el-button></td></tr></tbody></table><div v-else class="empty"><h3>还没有提取任务</h3><p>导入资料不自动创建个人抽取任务。日常聊天结束后才会进入处理链路。</p></div></section><div class="dashboard-grid"><section class="panel"><h2>模型与连接</h2><dl><template v-for="(item,role) in data.models" :key="role"><dt>{{ role==='main'?'对话模型':role==='fast'?'辅助模型':'Embedding' }}</dt><dd>{{ item.model||'未配置' }} <el-tag size="small" :type="item.ready?'success':'warning'">{{ item.ready?'配置就绪':'待配置' }}</el-tag></dd></template></dl><p>配置就绪不代表刚刚发起过推理；此页不会测试或泄露凭据。</p><div v-for="server in data.integrations" :key="server.name" class="health-row"><span>{{ server.name }}</span><strong>{{ !server.enabled?'未启用':server.connected?'已连接 · '+server.tool_count+' 个工具':'未连接' }}</strong></div><p v-if="!data.integrations.length">可选集成 {{ labels[data.integration_startup.state]??data.integration_startup.state }}；暂未载入连接。</p></section><section class="panel"><h2>索引与数据</h2><div class="health-row"><span>可用于本人记忆的原话</span><strong>{{ data.counts.eligible_personal_messages }}</strong></div><div class="health-row"><span>当前模型普通记忆向量</span><strong>{{ data.indexes.memory_vectors }}</strong></div><div class="health-row"><span>普通记忆分块</span><strong>{{ data.indexes.memory_chunks }}</strong></div><div class="health-row"><span>本人经历原文块</span><strong>{{ data.indexes.experience_chunks }}</strong></div><div class="health-row"><span>经历向量缓存</span><strong>{{ data.indexes.experience_vectors }}</strong></div><p>原文经历可以独立于长期事实检索。缓存条目数量不等于最终可用证据，也不等于质量或长期效果。</p></section></div></template><el-dialog :model-value="!!retry" title="重试失败的提取任务" width="440px" @close="retry=null"><p>将重新调用已配置的提取模型，可能产生费用；只重试这一条失败任务，不批量重放历史。</p><el-checkbox v-model="checked">确认重试该任务</el-checkbox><template #footer><el-button @click="retry=null">取消</el-button><el-button type="primary" :disabled="!checked" :loading="loading" @click="retryJob">确认重试</el-button></template></el-dialog></template>
